&lt;a href=&quot;/Wiki/Pathfinder-RPG.Aventures occultes (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Occult Adventures/Aventures occultes&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoOA.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;
&lt;i&gt;Les dons marqu&#233;s d&#39;un † sont des dons de combat accessibles en tant que don suppl&#233;mentaire aux bretteurs, guerriers, lutteurs, pistoliers et pr&#234;tres combattants.&lt;/i&gt;
&lt;script type=&quot;text/javascript&quot;&gt;
$(filtrable_init);

function filtrable_init() {
    // Find all tables with class filtrable and make them filtrable
    $(&quot;table.filtrable&quot;).each(makeFiltrable);
}

function makeFiltrable() {
    var table = $(this);
    var rows = table.find(&quot;tr&quot;);
    if (rows.length &lt; 2) {
        return;
    }
    var firstRow = rows.first();
    var cells = firstRow.children(&quot;td,th&quot;);
    table.get()[0].filters = [];
    cells.each(function (idx) {
        var contents = $(this).html;
        var filterLogo = $(&quot;&lt;img height=&#39;12px&#39; /&gt;&quot;);
        filterLogo.attr(&#39;src&#39;, &#39;/wiki/public/Upload/Battlemaps/Boutons/filter.png&#39;);
        filterLogo.attr(&#39;title&#39;, &#39;Cliquez ici pour filtrer les donn&#233;es&#39;);
        filterLogo.css(&#39;padding&#39;, &#39;0&#39;);
        filterLogo.click(doFilter(idx,filterLogo,table));
        $(this).prepend(filterLogo);
        table.get()[0].filters.push(null);
    });
}
function doFilter(nCol, logo, table) {
    return function () {
        var filter = prompt(&quot;Entrez le filtre &#224; appliquer.\nLaisser le cadre vide pour tout afficher; utilisez &#39;mot1|mot2&#39; pour un choix multiple.&quot;, &quot;&quot;).trim();
        if (filter == &quot;&quot;) {
            table.get()[0].filters[nCol] = null;
            logo.css(&quot;background-color&quot;, &quot;&quot;);
            logo.attr(&quot;title&quot;,&quot;Filtre actuel : aucun - cliquez pour changer le filtre&quot;);
        } else {
            table.get()[0].filters[nCol] = new RegExp(filter.trim(),&quot;i&quot;);
            logo.css(&quot;background-color&quot;, &quot;yellow&quot;);
            logo.attr(&quot;title&quot;,&quot;Filtre actuel : &quot; + (filter == &quot;&quot; ? &quot;aucun&quot; : filter)
                + &quot; - cliquez pour changer le filtre&quot;);
        }
        applyFilter(table);
    };
}
function applyFilter(table) {
    var rows = table.find(&quot;tr&quot;).filter(function (idx) {
        return idx &gt; 0 &amp;&amp; $(this).children(&quot;th&quot;).length == 0;
    });
    rows.each(function () {
        var keep = mustKeep(this,table.get()[0].filters);
        $(this).css(&quot;display&quot;, keep ? &quot;table-row&quot; : &quot;none&quot;);
    });
}
function mustKeep(row,filters) {
    var cells = $(row).children(&quot;td&quot;);
    var nCols = filters.length;
    var keep = true;
    var iCol = 0;
    while (keep &amp;&amp; iCol &lt; nCols) {
        keep = filters[iCol] === null ||
            cells.eq(iCol).html().match(filters[iCol]) != null;
        iCol++;
    }
    return keep;
}
&lt;/script&gt;&lt;br /&gt;&lt;br /&gt;&lt;center&gt;
&lt;table CLASS=&quot;tablo autoalt toutgauche filtrable&quot;&gt;&lt;caption&gt;Tableau r&#233;capitulatif des dons&lt;/caption&gt;&lt;tr CLASS=&quot;titre&quot;&gt;&lt;td WIDTH=&quot;30%&quot;&gt;Dons&lt;/td&gt;&lt;td WIDTH=&quot;25%&quot;&gt;Conditions&lt;/td&gt;&lt;td WIDTH=&quot;45%&quot;&gt;Avantages&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Adepte-De-La-Discipline.html&quot; title=&quot;Adepte de la discipline&quot;&gt;Adepte de la discipline&lt;/a&gt; &lt;sup&gt;AO&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Pouvoir de classe &lt;a class=&quot;pagelink&quot; href=&quot;Psychiste.html#DISCIPLINEPSYCHIQUE&quot; title=&quot;Le psychiste&quot;&gt;discipline psychique&lt;/a&gt;&lt;/td&gt;&lt;td&gt;+1 aux tests de &lt;a class=&quot;pagelink&quot; href=&quot;Lancer-Des-Sorts#Nls.html&quot; title=&quot;NLS&quot;&gt;niveau de lanceur de sorts&lt;/a&gt;, de &lt;a class=&quot;pagelink&quot; href=&quot;Lancer-Des-Sorts.html#CONCENTRATION&quot; title=&quot;Lancer des sorts&quot;&gt;concentration&lt;/a&gt; et aux &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;jet de sauvegarde&quot;&gt;jets de sauvegarde&lt;/a&gt; pour les sorts de discipline&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;&#194;me-Commune.html&quot; title=&quot;&#194;me commune&quot;&gt;&#194;me commune&lt;/a&gt; &lt;sup&gt;AO&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Pouvoir de classe &lt;a class=&quot;pagelink&quot; href=&quot;Spirite.html#PARTAGEDECONSCIENCE&quot; title=&quot;Le spirite&quot;&gt;partage de conscience&lt;/a&gt;&lt;/td&gt;&lt;td&gt;Le fant&#244;me offre une protection contre les &lt;a class=&quot;pagelink&quot; href=&quot;Cr&#233;er-Un-Sort.html#MORT&quot; title=&quot;Cr&#233;er un sort&quot;&gt;effets de mort&lt;/a&gt;, l’&lt;a class=&quot;pagelink&quot; href=&quot;&#201;nergie-N&#233;gative.html&quot; title=&quot;&#201;nergie n&#233;gative&quot;&gt;&#233;nergie n&#233;gative&lt;/a&gt; et la &lt;a class=&quot;pagelink&quot; href=&quot;Possession-Spirituelle.html&quot; title=&quot;La possession&quot;&gt;possession&lt;/a&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Amplification-Suppl&#233;mentaire.html&quot; title=&quot;Amplification suppl&#233;mentaire&quot;&gt;Amplification suppl&#233;mentaire&lt;/a&gt; &lt;sup&gt;AO&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Pouvoir de classe &lt;a class=&quot;pagelink&quot; href=&quot;Psychiste.html#AMPLIFICATIONPHRENIQUE&quot; title=&quot;Le psychiste&quot;&gt;amplification phr&#233;nique&lt;/a&gt;&lt;/td&gt;&lt;td&gt;Une &lt;a class=&quot;pagelink&quot; href=&quot;Psychiste.html#AMPLIFICATIONPHRENIQUE&quot; title=&quot;Le psychiste&quot;&gt;amplification phr&#233;nique&lt;/a&gt; suppl&#233;mentaire&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Appel-Spirituel.html&quot; title=&quot;Appel spirituel&quot;&gt;Appel spirituel&lt;/a&gt; &lt;sup&gt;AO&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Pouvoir de classe &lt;a class=&quot;pagelink&quot; href=&quot;Spirite.html#FANTOME&quot; title=&quot;Le spirite&quot;&gt;fant&#244;me&lt;/a&gt;&lt;/td&gt;&lt;td&gt;Le fant&#244;me gagne un bonus lors de son invocation&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Briser-Le-Masque-Mental.html&quot; title=&quot;Briser le masque mental&quot;&gt;Briser le masque mental&lt;/a&gt;† &lt;sup&gt;AO&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sensibilit&#233;-Psychique.html&quot; title=&quot;Sensibilit&#233; psychique&quot;&gt;Sensibilit&#233; psychique&lt;/a&gt; ou capacit&#233; &#224; lancer des sorts psychiques ou &#224; utiliser des pouvoirs magiques psychiques, personnage niveau 2&lt;/td&gt;&lt;td&gt;Les manifestations offensives avec un jet de Volont&#233; r&#233;v&#232;lent la v&#233;ritable forme de l’adversaire&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Changement-De-Focalisation-Efficace.html&quot; title=&quot;Changement de focalisation efficace&quot;&gt;Changement de focalisation efficace&lt;/a&gt; &lt;sup&gt;AO&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Occultiste.html&quot; title=&quot;L&amp;#39;occultiste&quot;&gt;Occultiste&lt;/a&gt; niveau 7&lt;/td&gt;&lt;td&gt;Changement de point de &lt;a class=&quot;pagelink&quot; href=&quot;Occultiste.html#FOCALISATIONMENTALE&quot; title=&quot;L&amp;#39;occultiste&quot;&gt;focalisation mentale&lt;/a&gt; sans aucune perte 2/jour&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Changement-Rapide-De-Focalisation.html&quot; title=&quot;Changement rapide de focalisation&quot;&gt;Changement rapide de focalisation&lt;/a&gt; &lt;sup&gt;AO&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Lancer-Des-Sorts#Nls.html&quot; title=&quot;NLS&quot;&gt;NLS&lt;/a&gt; 5, pouvoir de classe &lt;a class=&quot;pagelink&quot; href=&quot;Occultiste.html#FOCALISATIONMENTALE&quot; title=&quot;L&amp;#39;occultiste&quot;&gt;focalisation mentale&lt;/a&gt;&lt;/td&gt;&lt;td&gt;Changement de &lt;a class=&quot;pagelink&quot; href=&quot;Occultiste.html#FOCALISATIONMENTALE&quot; title=&quot;L&amp;#39;occultiste&quot;&gt;focalisation mentale&lt;/a&gt; plus rapide 1/jour&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Combattant-Psychique.html&quot; title=&quot;Combattant psychique&quot;&gt;Combattant psychique&lt;/a&gt;† &lt;sup&gt;AO&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Intelligence.html&quot; title=&quot;L&amp;#39;Intelligence&quot;&gt;Int&lt;/a&gt; 13, &lt;a class=&quot;pagelink&quot; href=&quot;Sensibilit&#233;-Psychique.html&quot; title=&quot;Sensibilit&#233; psychique&quot;&gt;Sensibilit&#233; psychique&lt;/a&gt; ou capacit&#233; &#224; lancer des sorts psychiques ou utiliser des pouvoirs magiques psychiques, personnage niveau 3&lt;/td&gt;&lt;td&gt;Gain de points de manifestation gratuits lors des &lt;a class=&quot;pagelink&quot; href=&quot;Duels-Psychiques.html&quot; title=&quot;Les duels psychiques&quot;&gt;duels psychiques&lt;/a&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Conduit-&#201;motionnel.html&quot; title=&quot;Conduit &#233;motionnel&quot;&gt;Conduit &#233;motionnel&lt;/a&gt; &lt;sup&gt;AO&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Pouvoir de classe &lt;a class=&quot;pagelink&quot; href=&quot;Spirite.html#PARTAGEDECONSCIENCE&quot; title=&quot;Le spirite&quot;&gt;partage de conscience&lt;/a&gt;&lt;/td&gt;&lt;td&gt;Gain de nouveaux sorts en fonction de l’&lt;a class=&quot;pagelink&quot; href=&quot;Fant&#244;mes-(Spirite).html#EMOTIONDOMINANTE&quot; title=&quot;Le fant&#244;me du spirite&quot;&gt;&#233;motion dominante du fant&#244;me&lt;/a&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Cr&#226;ne-Allong&#233;.html&quot; title=&quot;Cr&#226;ne allong&#233;&quot;&gt;Cr&#226;ne allong&#233;&lt;/a&gt; &lt;sup&gt;AO&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;—&lt;/td&gt;&lt;td&gt;Bonus et malus en fonction de la forme de cr&#226;ne choisie&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;D&#233;fense-Fantomatique.html&quot; title=&quot;D&#233;fense fantomatique&quot;&gt;D&#233;fense fantomatique&lt;/a&gt; &lt;sup&gt;AO&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Pouvoir de classe &lt;a class=&quot;pagelink&quot; href=&quot;Spirite.html#FANTOME&quot; title=&quot;Le spirite&quot;&gt;fant&#244;me&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Fant&#244;mes-(Spirite).html&quot; title=&quot;Le fant&#244;me du spirite&quot;&gt;fant&#244;me&lt;/a&gt; dot&#233; du pouvoir &lt;a class=&quot;pagelink&quot; href=&quot;Fant&#244;mes-(Spirite).html#VOLINTANGIBLE&quot; title=&quot;Le fant&#244;me du spirite&quot;&gt;vol sous forme intangible&lt;/a&gt;&lt;/td&gt;&lt;td&gt;Le fant&#244;me a des chances d’ignorer les coups critiques et les d&#233;g&#226;ts de pr&#233;cision&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;D&#233;fenseur-Psychique.html&quot; title=&quot;D&#233;fenseur psychique&quot;&gt;D&#233;fenseur psychique&lt;/a&gt; &lt;sup&gt;AO&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Intelligence.html&quot; title=&quot;L&amp;#39;Intelligence&quot;&gt;Int&lt;/a&gt; 13, &lt;a class=&quot;pagelink&quot; href=&quot;Sensibilit&#233;-Psychique.html&quot; title=&quot;Sensibilit&#233; psychique&quot;&gt;Sensibilit&#233; psychique&lt;/a&gt; ou capacit&#233; &#224; lancer des sorts psychiques ou utiliser des pouvoirs magiques psychiques, personnage niveau 3&lt;/td&gt;&lt;td&gt;Gain de points de vie temporaires au d&#233;but d’un &lt;a class=&quot;pagelink&quot; href=&quot;Duels-Psychiques.html&quot; title=&quot;Les duels psychiques&quot;&gt;duel psychique&lt;/a&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Douleur-Compos&#233;e.html&quot; title=&quot;Douleur compos&#233;e&quot;&gt;Douleur compos&#233;e&lt;/a&gt;† &lt;sup&gt;AO&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Hypnotiseur.html&quot; title=&quot;L&amp;#39;hypnotiseur&quot;&gt;Hypnotiseur&lt;/a&gt; de niveau 13, pouvoir de classe &lt;a class=&quot;pagelink&quot; href=&quot;Hypnotiseur.html#REGARDDOULOUREUX&quot; title=&quot;L&amp;#39;hypnotiseur&quot;&gt;regard douloureux&lt;/a&gt;&lt;/td&gt;&lt;td&gt;Applique les effets de deux dons de regard au &lt;a class=&quot;pagelink&quot; href=&quot;Hypnotiseur.html#REGARDDOULOUREUX&quot; title=&quot;L&amp;#39;hypnotiseur&quot;&gt;regard douloureux&lt;/a&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Empathe.html&quot; title=&quot;Empathe&quot;&gt;Empathe&lt;/a&gt; &lt;sup&gt;AO&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sensibilit&#233;-Psychique.html&quot; title=&quot;Sensibilit&#233; psychique&quot;&gt;Sensibilit&#233; psychique&lt;/a&gt; ou capacit&#233; &#224; lancer des sorts psychiques, 1 rang en &lt;a class=&quot;pagelink&quot; href=&quot;Perception.html&quot; title=&quot;Perception&quot;&gt;Perception&lt;/a&gt; ou en &lt;a class=&quot;pagelink&quot; href=&quot;Psychologie.html&quot; title=&quot;Psychologie&quot;&gt;Psychologie&lt;/a&gt;&lt;/td&gt;&lt;td&gt;Lecture rapide et fr&#233;quente des &#233;motions mais rend l’esprit vuln&#233;rable&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;&#201;quilibre-Spirituel.html&quot; title=&quot;&#201;quilibre spirituel&quot;&gt;&#201;quilibre spirituel&lt;/a&gt; &lt;sup&gt;AO&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Pouvoirs de classe &lt;a class=&quot;pagelink&quot; href=&quot;Moine.html#RESERVEDEKI&quot; title=&quot;Le moine&quot;&gt;r&#233;serve de ki&lt;/a&gt; et &lt;a class=&quot;pagelink&quot; href=&quot;Moine.html#SERENITE&quot; title=&quot;Le moine&quot;&gt;s&#233;r&#233;nit&#233;&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Moine.html#SERENITE&quot; title=&quot;Le moine&quot;&gt;S&#233;r&#233;nit&#233;&lt;/a&gt; s’applique contre la &lt;a class=&quot;pagelink&quot; href=&quot;Possession-Spirituelle.html&quot; title=&quot;La possession&quot;&gt;possession&lt;/a&gt;, d&#233;pense de ki pour doubler le bonus&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Esprit-Concentr&#233;.html&quot; title=&quot;Esprit concentr&